def transform_v2(grid):
    H,W=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    blocks=[]
    for r in range(H-1):
        for c in range(W-1):
            if grid[r][c] == grid[r][c+1] == grid[r+1][c] == grid[r+1][c+1] == 2:
                blocks.append((r,c))
    markers=[]
    raydirs=[(-1,-1),(-1,1),(1,-1),(1,1)]
    # Colors rotate counterclockwise among TL, TR, BR, BL: each ray receives the prior clockwise corner's color.
    for r,c in blocks:
        pos=[(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]
        vals=[grid[rr][cc] if 0<=rr<H and 0<=cc<W else 0 for rr,cc in pos]
        for i,(rr,cc) in enumerate(pos):
            if 0<=rr<H and 0<=cc<W and vals[i] not in (0,2):
                color=vals[[2,0,3,1][i]]
                markers.append((rr,cc,color,raydirs[i]))
    marker_positions={(r,c) for r,c,_,_ in markers}
    for r,c,color,_ in markers: out[r][c]=color
    for r,c,color,(dr,dc) in markers:
        rr,cc=r+dr,c+dc
        while 0<=rr<H and 0<=cc<W:
            if grid[rr][cc] != 0 or (rr,cc) in marker_positions:
                break
            # An approaching ray terminates at the outside-left edge of another 2x2's top row.
            if any(rr==br and cc<bc for br,bc in blocks):
                break
            out[rr][cc]=color
            rr+=dr;cc+=dc
    return out
