def transform_v3(grid):
    H,W=len(grid),len(grid[0]); out=[row[:] for row in grid]
    blocks=[]
    for r in range(H-1):
        for c in range(W-1):
            if grid[r][c]==grid[r][c+1]==grid[r+1][c]==grid[r+1][c+1]==2: blocks.append((r,c))
    markers=[]; dirs=[(-1,-1),(-1,1),(1,-1),(1,1)]; srcidx=[2,0,3,1]
    for br,bc in blocks:
        ps=[(br-1,bc-1),(br-1,bc+2),(br+2,bc-1),(br+2,bc+2)]
        vals=[grid[r][c] if 0<=r<H and 0<=c<W else 0 for r,c in ps]
        for i,(r,c) in enumerate(ps):
            if 0<=r<H and 0<=c<W and vals[i] not in (0,2): markers.append((r,c,vals[srcidx[i]],dirs[i]))
    mpos={(r,c) for r,c,_,_ in markers}
    for r,c,color,_ in markers: out[r][c]=color
    for r,c,color,(dr,dc) in markers:
        r+=dr;c+=dc
        while 0<=r<H and 0<=c<W:
            if grid[r][c]!=0 or (r,c) in mpos: break
            if any(r==br and c==bc-1 for br,bc in blocks): break
            out[r][c]=color
            r+=dr;c+=dc
    return out
