def transform_final(grid):
    height, width = len(grid), len(grid[0])
    output = [row[:] for row in grid]
    blocks = [
        (r, c)
        for r in range(height - 1)
        for c in range(width - 1)
        if grid[r][c] == grid[r][c + 1] == grid[r + 1][c] == grid[r + 1][c + 1] == 2
    ]
    directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
    source_indices = [2, 0, 3, 1]
    rays = []
    for r, c in blocks:
        positions = [(r - 1, c - 1), (r - 1, c + 2), (r + 2, c - 1), (r + 2, c + 2)]
        colors = [grid[rr][cc] if 0 <= rr < height and 0 <= cc < width else 0 for rr, cc in positions]
        for i, (rr, cc) in enumerate(positions):
            if 0 <= rr < height and 0 <= cc < width and colors[i] not in (0, 2):
                rays.append((rr, cc, colors[source_indices[i]], directions[i]))
    marker_positions = {(r, c) for r, c, _, _ in rays}
    for r, c, color, _ in rays:
        output[r][c] = color
    for r, c, color, (dr, dc) in rays:
        rr, cc = r + dr, c + dc
        while 0 <= rr < height and 0 <= cc < width:
            if grid[rr][cc] != 0 or (rr, cc) in marker_positions:
                break
            if any(rr == br and cc == bc - 1 for br, bc in blocks) and rr not in (0, height - 1) and cc not in (0, width - 1):
                break
            output[rr][cc] = color
            rr += dr
            cc += dc
    return output
